<script setup lang="ts">
import { shallowRef, computed, onMounted, ref, inject } from 'vue';
import holiday_jp from '@holiday-jp/holiday_jp'
import { Dialog, GanttColumnData, Task } from '@/interface/globalInterface';
import GanttColumn from './GanttColumn.vue'
import GanttTaskPopup from '@/components/Task/Gantt/GanttTaskPopup.vue';
import { DateTime, DateTimeUnit, Interval } from 'luxon';
import { useMenuStore } from '@/store/menu';
import { Project } from '@/interface/projectInterface';
const props = defineProps<{
    selectedMonth: number
    selectedYear: number
    projects: Project[]
    activeProject: Project | null
    viewType: DateTimeUnit
    fromSpan: string
    toSpan: string
    maxInterval: Interval
}>()
const emit = defineEmits<{
    setViewType: [value: DateTimeUnit]
}>()
const sortSelection: {label:string, value:DateTimeUnit}[] = [{label: '年', value: 'year'}, {label: '月', value: 'month'}, {label: '日', value: 'day'}]
const menu = useMenuStore()
const layer = shallowRef(0)
const { info } = inject<Dialog>('dialog')!
const holidays = computed(() => {
    const holidays = holiday_jp.between(new Date(props.selectedYear - 1 + '-12-01'), new Date(props.selectedYear + 1 + '-1-31'));
    return holidays
})

const calendarData = computed(() => {
    const thisMonth = DateTime.fromObject({year: props.selectedYear, month: props.selectedMonth})
    const min:DateTime | null = props.maxInterval.start?.isValid ? props.maxInterval.start : null
    const max:DateTime | null = props.maxInterval.end?.isValid ? props.maxInterval.end : null
    const intervalStart = props.viewType == 'year' ? (min ? min : DateTime.now().minus({year: 1}).startOf('year')) : props.viewType == 'month' ? thisMonth.startOf('year') : thisMonth.startOf('month')
    const intervalEnd = props.viewType == 'year' ? (max ? max : DateTime.now().plus({year: 1}).endOf('year')) : props.viewType == 'month' ? thisMonth.endOf('year') : thisMonth.endOf('month')
    const interval = Interval.fromDateTimes(intervalStart, intervalEnd)

    if( !interval.isValid) return []
    const calendar:GanttColumnData[] = [];
    let current = interval.start
    while(current < interval.end){
        const index = props.viewType
        const holiday = index == 'day' ? holidays.value.find(h => DateTime.fromISO(h.date.toISOString()).hasSame(current, 'day')) : null;
        let projects = orderCreator(0, props.projects).filter(ob => DateTime.fromISO(ob.pseudo_start as string).hasSame(current, index))
   
        calendar.push({ 
            "date_short" : current[index],
            "date_full" : current.toISODate()!,
            "is_holiday" : holiday ? holiday.name : null,
            "projects": projects            
        });
        
        current = current.plus({[index]: 1})
    }
    return calendar

})
const orderCreator = (order:number, list:Project[]) => {
    
    let break_point_rear:DateTime = DateTime.now()[props.viewType];
    let cooked:Project[] = [];
    let reserved:Project[] = [];
    for (let i = 0; i < list.length; i++) {
        let item = list[i]
        if(i == 0){
            item['order'] = order
            cooked.push(item)
            break_point_rear = DateTime.fromSQL(item.pseudo_end!)[props.viewType]
        }else{
            if(DateTime.fromSQL(item.pseudo_start!)[props.viewType] > break_point_rear){
                item['order'] = order
                cooked.push(item)
                break_point_rear = DateTime.fromSQL(item.pseudo_end!)[props.viewType]
            }
            else{
                reserved.push(item)
            }
        }
    }
    if(reserved.length){
        let uld = orderCreator(order + 1, reserved);
        cooked = cooked.concat(uld)
    }
    if(layer.value < order){
        layer.value = order
    }
    return cooked       
}
const unit = computed(() => {
    return calendarData.value.length && calendarData.value.length > 7 ? calendarData.value.length : 7
})
const switchView = () => {
    let newVal:DateTimeUnit = props.viewType == 'year' ? 'month' : props.viewType == 'month' ? 'day' : 'year'
    let label = sortSelection.find(s => s.value == newVal)?.label
    info(`表示形式を${label}に変更しました`)
    emit('setViewType', newVal)
}
</script>
<style scoped>
.gantt-content {
    min-width: 100%;

}
@media screen and (max-width: 959px) {
    .gantt-content{
        min-width: calc(100vw / 7 * v-bind(unit));
    }
}
</style>